void mainImage(out vec4 couleurSortie, vec2 coordonneesPixel) {
    vec3 resolution = iResolution;
    vec2 coordonneesNormalisees = (coordonneesPixel + coordonneesPixel - resolution.xy) / resolution.y;

    couleurSortie = vec4(0.0);

    for (float indexParticule = 0.0; indexParticule < 700.0; indexParticule++) {
        vec3 valeurAleatoire = fract(sin((indexParticule + vec3(1.0, 8.7, 3.7)) * 3000.0) * 4000.0);

        float vitesse = 0.8 + 0.4 * valeurAleatoire.y;
        float tempsEcoule = (iTime * vitesse) + valeurAleatoire.z * 10.0;

        float dureeTotale = 6.0;
        float tempsLoop = mod(tempsEcoule, dureeTotale);

        float nbMarches = 6.0;
        float etageActuel = floor(tempsLoop);
        float tFraction = fract(tempsLoop);

        float rapportAspect = resolution.x / resolution.y;
        float etendueX = rapportAspect * 2.8;

        float directionDiagonale = 0.35;
        float xInitial = (valeurAleatoire.x - 0.5) * etendueX - (etageActuel * directionDiagonale);

        float vitesseRoulement = 0.18 + 0.08 * valeurAleatoire.y;
        float positionX = xInitial + (etageActuel + tFraction) * vitesseRoulement;

        float hauterMarche = 0.38;
        float hauteurBase = 1.1 - etageActuel * hauterMarche;

        float gravite = 4.0;
        float chuteY = 0.5 * gravite * tFraction * tFraction * hauterMarche;
        float positionY = hauteurBase - chuteY;

        vec2 positionParticule = vec2(positionX, positionY);
        float distanceParticule = length(coordonneesNormalisees - positionParticule);

        vec4 couleurParticule = 0.5 + 0.5 * cos(6.28318 * (valeurAleatoire.y + vec4(0.0, 0.33, 0.67, 0.0)));

        float fonduEntree = smoothstep(0.0, 0.15, tempsLoop);
        float fonduSortie = smoothstep(dureeTotale, dureeTotale - 0.3, tempsLoop);
        float visibilite = fonduEntree * fonduSortie;

        float rayonPixel = 1.5 / resolution.y;
        float coeurNet = smoothstep(rayonPixel, 0.0, distanceParticule);
        float haloFluide = 0.000015 / (distanceParticule * distanceParticule + 0.000008);

        float intensiteLumiere = coeurNet * 2.5 + haloFluide;

        couleurSortie += couleurParticule * visibilite * intensiteLumiere;
    }
}
